    /// An amendment re-issues every clause as `goal:<slug>@constitution:vN`,
    /// so the id a task was created under yesterday is not the id its successor
    /// is created under today. Matching goals with an exact string compare
    /// therefore hides the completed work from the retry, and reports
    /// `already_serving_this_goal: 0` for work that plainly exists — which is
    /// the same defect as the binding comparison fixed earlier, in a second
    /// place that was never migrated. `goal_slug` already exists and
    /// `store::goals` already uses it.
    ///
    /// Measured on the live board: 11 titles were created more than once across
    /// 29 tasks, and 5 of those spread their attempts across ids sharing one
    /// slug. "Carry controls across an amendment" was created six times — the
    /// one that finished under `@constitution:v2`, and five abandoned retries
    /// under the bare slug, every one of them blind to the finished work.
    #[test]
    fn existing_work_finds_prior_work_across_a_constitution_amendment() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Carry controls", "carry them", None)
            .unwrap();
        // The same clause re-issued into an amendment: same slug, versioned id.
        let carried = e
            .store
            .define_clause_in_version(
                GoalKind::Constraint,
                "Carry controls",
                "carry them",
                "constitution:v2",
                1_000,
            )
            .unwrap();
        assert_eq!(carried.slug, goal.slug, "the amendment keeps the slug");
        assert_ne!(carried.id, goal.id, "and changes the id");

        let finished = e
            .store
            .create_task(
                &carried.id,
                "Carry controls across an amendment",
                "done",
                None,
                1_000,
            )
            .unwrap();

        // The retry names the bare slug, which is what an agent reaching for
        // the goal by name actually passes.
        let found = e.existing_work(Some(&goal.id), &[]).unwrap();
        assert!(
            found.iter().any(|t| t.id == finished.id),
            "the retry must see the work already finished under the versioned id"
        );

        // And the reverse: work created under the bare slug is visible to a
        // task asking under the versioned id.
        let bare = e
            .store
            .create_task(
                &goal.id,
                "Carry controls across an amendment",
                "done",
                None,
                1_001,
            )
            .unwrap();
        let both = e.existing_work(Some(&carried.id), &[]).unwrap();
        let ids: Vec<&str> = both.iter().map(|t| t.id.as_str()).collect();
        assert!(
            ids.contains(&finished.id.as_str()) && ids.contains(&bare.id.as_str()),
            "both forms of the same goal are the same goal: {ids:?}"
        );
    }

    /// ADR-0046 gave agents a way to address a peer and nothing ever used it:
    /// in an eight-hour session `pending_questions` stayed empty while five
    /// tasks waited on a human. Nothing surfaced that there *was* a question to
    /// ask. A scope collision is a fact the ledger already holds, so the draft
    /// must be produced from it with no model involved at all — this engine
    /// points at an unreachable endpoint.
    #[test]
    fn a_colliding_claim_produces_an_addressed_draft_with_no_model_reachable() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let mine = engine
            .create_task(&goal.id, "Split the ingest module", "done")
            .unwrap();
        let theirs = engine
            .create_task(&goal.id, "Rename the ingest entry point", "done")
            .unwrap();
        let scope = TaskScope {
            paths: vec!["crates/mindleak-core/src/ingest/**".to_string()],
            symbols: vec![],
        };
        assert!(engine
            .claim_task_with_scope(&theirs.id, "session:v1:peer", 600, &scope)
            .unwrap());
        assert!(engine
            .claim_task_with_scope(&mine.id, "session:v1:mine", 600, &scope)
            .unwrap());

        let drafts = engine.draft_questions(&mine.id).unwrap();

        assert_eq!(drafts.len(), 1, "one peer collides: {drafts:?}");
        let draft = &drafts[0];
        // Addressed at the peer's agent id, ready to hand to ask_question.
        assert_eq!(draft.audience, "session:v1:peer");
        assert_eq!(draft.their_task_id, theirs.id);
        assert_eq!(draft.their_title, "Rename the ingest entry point");
        assert_eq!(
            draft.drafted_by,
            DraftedBy::Template,
            "no model is reachable, so the template must carry it"
        );
        assert_eq!(draft.model_call.source, ModelCallSource::Fallback);
        assert_eq!(
            draft.model_call.fallback_reason,
            Some(ModelFailureReason::Unreachable)
        );
        assert!(draft.question.contains("Split the ingest module"));
        assert!(!draft.matching_paths.is_empty());
    }

    /// Drafting is a proposal, never a message. Nothing may be recorded or
    /// parked until the caller decides to call `ask_question` — otherwise a
    /// suggestion nobody sent would still land on the durable thread.
    #[test]
    fn drafting_records_nothing_and_parks_nothing() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let mine = engine.create_task(&goal.id, "Mine", "done").unwrap();
        let theirs = engine.create_task(&goal.id, "Theirs", "done").unwrap();
        let scope = TaskScope {
            paths: vec!["src/**".to_string()],
            symbols: vec![],
        };
        engine
            .claim_task_with_scope(&theirs.id, "session:v1:peer", 600, &scope)
            .unwrap();
        engine
            .claim_task_with_scope(&mine.id, "session:v1:mine", 600, &scope)
            .unwrap();

        assert_eq!(engine.draft_questions(&mine.id).unwrap().len(), 1);

        let board = engine.board(false).unwrap();
        let after = board.iter().find(|task| task.id == mine.id).unwrap();
        assert_eq!(
            after.status,
            TaskStatus::Claimed,
            "a draft must not park the task"
        );
        assert!(
            engine.task_qa(&mine.id).unwrap().is_empty(),
            "a draft must not touch the durable thread"
        );
        assert!(engine
            .pending_questions("session:v1:peer")
            .unwrap()
            .is_empty());
    }

    /// ADR-0046 clause 6 refuses a self-addressed question: it parks the task
    /// waiting on the only agent that cannot act while it is parked. One agent
    /// holding two overlapping tasks is ordinary, so this is a skip, not an
    /// error.
    #[test]
    fn an_agent_is_never_told_to_ask_itself() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let first = engine.create_task(&goal.id, "First", "done").unwrap();
        let second = engine.create_task(&goal.id, "Second", "done").unwrap();
        let scope = TaskScope {
            paths: vec!["src/**".to_string()],
            symbols: vec![],
        };
        engine
            .claim_task_with_scope(&first.id, "session:v1:solo", 600, &scope)
            .unwrap();
        engine
            .claim_task_with_scope(&second.id, "session:v1:solo", 600, &scope)
            .unwrap();

        assert!(engine.draft_questions(&second.id).unwrap().is_empty());
    }

    #[test]
    fn a_task_that_collides_with_nobody_proposes_nothing() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let alone = engine.create_task(&goal.id, "Alone", "done").unwrap();
        engine
            .claim_task_with_scope(
                &alone.id,
                "session:v1:mine",
                600,
                &TaskScope {
                    paths: vec!["docs/**".to_string()],
                    symbols: vec![],
                },
            )
            .unwrap();

        assert!(engine.draft_questions(&alone.id).unwrap().is_empty());
    }

    /// The gap: `pending_questions` matches an agent id, and a human has no
    /// agent id — `audience IS NULL` *is* the addressing (ADR-0046 clause 2).
    /// So there was no way to list what was waiting on a person at all. Five
    /// tasks sat `awaiting_human` for up to seventy-five hours with no surface
    /// that could show them.
    #[test]
    fn questions_addressed_at_a_human_are_listable_and_agent_addressed_ones_are_not() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let for_human = engine
            .create_task(&goal.id, "Pilot the release", "done")
            .unwrap();
        let for_peer = engine
            .create_task(&goal.id, "Rename the facade", "done")
            .unwrap();
        engine
            .claim_task(&for_human.id, "session:v1:asker", 600)
            .unwrap();
        engine
            .claim_task(&for_peer.id, "session:v1:asker", 600)
            .unwrap();

        engine
            .ask_question(
                &for_human.id,
                "session:v1:asker",
                "Which registry should the pilot publish to?",
                None,
            )
            .unwrap();
        engine
            .ask_question(
                &for_peer.id,
                "session:v1:asker",
                "Are you renaming this too?",
                Some("session:v1:peer"),
            )
            .unwrap();

        let inbox = engine.questions_for_a_human().unwrap();

        assert_eq!(inbox.len(), 1, "only the human-addressed one: {inbox:?}");
        let waiting = &inbox[0];
        assert_eq!(waiting.task_id, for_human.id);
        // The title travels with it: an inbox that needs a lookup per row to
        // say what it is about is not an inbox.
        assert_eq!(waiting.task_title, "Pilot the release");
        assert_eq!(waiting.asked_by, "session:v1:asker");
        assert_eq!(
            waiting.question,
            "Which registry should the pilot publish to?"
        );
        assert!(waiting.waiting_seconds >= 0);

        // The peer-addressed question belongs to the peer, not to the human.
        assert_eq!(
            engine.pending_questions("session:v1:peer").unwrap().len(),
            1
        );
    }

    /// Answering must clear it. A question that survives its own answer would
    /// have a person reply twice to the same thing.
    #[test]
    fn an_answered_question_leaves_the_human_inbox() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine
            .create_task(&goal.id, "Pilot the release", "done")
            .unwrap();
        engine
            .claim_task(&task.id, "session:v1:asker", 600)
            .unwrap();
        engine
            .ask_question(&task.id, "session:v1:asker", "Which registry?", None)
            .unwrap();
        assert_eq!(engine.questions_for_a_human().unwrap().len(), 1);

        assert!(engine
            .answer_question(&task.id, "The public one.", "Lyndon Swan", 600)
            .unwrap());

        assert!(engine.questions_for_a_human().unwrap().is_empty());
        let board = engine.board(false).unwrap();
        let resumed = board.iter().find(|t| t.id == task.id).unwrap();
        assert_eq!(
            resumed.status,
            TaskStatus::Claimed,
            "answering resumes the agent that asked"
        );
        assert_eq!(resumed.owner.as_deref(), Some("session:v1:asker"));
    }

    /// Reading is not consuming (ADR-0046 clause 4). Two people looking at the
    /// inbox must see the same rows, or one of them silently loses a question.
    ///
    /// `waiting_seconds` is deliberately normalised before comparing. It is
    /// derived at read time as `now - asked_at`, not stored, so two reads that
    /// straddle a one-second boundary differ in it legitimately — comparing it
    /// made this test fail in CI (run 33361472735) on a change that touched no
    /// Rust, for a reason that has nothing to do with consumption. Every other
    /// field is still compared exactly, so a read that consumed, reordered, or
    /// altered a question still fails here. `only_waiting_seconds_moves_with_
    /// the_clock` in `store::coordination::questions` pins the assumption that
    /// makes this exclusion safe.
    #[test]
    fn reading_the_inbox_does_not_consume_it() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Pilot", "done").unwrap();
        engine
            .claim_task(&task.id, "session:v1:asker", 600)
            .unwrap();
        engine
            .ask_question(&task.id, "session:v1:asker", "Which registry?", None)
            .unwrap();

        let first = engine.questions_for_a_human().unwrap();
        let second = engine.questions_for_a_human().unwrap();

        let ignoring_elapsed = |questions: &[crate::HumanQuestion]| {
            questions
                .iter()
                .map(|question| crate::HumanQuestion {
                    waiting_seconds: 0,
                    ..question.clone()
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(ignoring_elapsed(&first), ignoring_elapsed(&second));
        assert_eq!(second.len(), 1);
    }

    #[test]
    fn facade_creates_progressive_handoff_chain() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Safe handoff", "serialize edits", None)
            .unwrap();
        let first = engine.create_task(&goal.id, "Edit first", "done").unwrap();
        let second = engine
            .create_task_after(&goal.id, "Edit second", "done", Some(first.id.clone()))
            .unwrap();

        assert_eq!(second.status, TaskStatus::Blocked);
        assert_eq!(second.blocked_by.as_deref(), Some(first.id.as_str()));
    }

    #[test]
    fn decompose_falls_back_to_single_task_without_llm() {
        let e = engine();
        let g = e
            .define_goal(
                GoalKind::Objective,
                "Add search",
                "Implement FTS search",
                None,
            )
            .unwrap();
        let tasks = e.decompose_goal(&g.id).unwrap();
        assert_eq!(tasks.len(), 1);
        assert!(tasks[0].title.contains("Add search"));
        assert_eq!(tasks[0].model_call.source, ModelCallSource::Fallback);
        assert_eq!(
            tasks[0].model_call.fallback_reason,
            Some(ModelFailureReason::Unreachable)
        );

        let serialized = serde_json::to_value(&tasks[0]).unwrap();
        assert_eq!(serialized["id"], tasks[0].id);
        assert!(serialized.get("task").is_none());
        assert_eq!(serialized["model_call"]["source"], "fallback");
        assert_eq!(serialized["model_call"]["fallback_reason"], "unreachable");
    }

    /// Bug: decomposition was additive, so every re-run produced another copy
    /// of the same drafts. Measured on 2026-08-11 the board carried three or
    /// four identical `Implement: ADR-NNNN` seeds for each of eight ADRs, and
    /// two sessions claimed different seeds for ADR-0090 and built it twice.
    /// Impact: `next_task` hands duplicates to different agents, and the
    /// overlap preflight cannot catch it, because a claim-time check is a race
    /// the second claimant always wins. Fix: a draft whose exact title already
    /// names live work under this goal resolves to that task.
    #[test]
    fn decomposing_a_goal_twice_does_not_produce_the_work_twice() {
        let e = engine();
        let g = e
            .define_goal(
                GoalKind::Objective,
                "Add search",
                "Implement FTS search",
                None,
            )
            .unwrap();

        let first = e.decompose_goal(&g.id).unwrap();
        let second = e.decompose_goal(&g.id).unwrap();

        assert_eq!(second.len(), first.len());
        assert_eq!(
            second[0].id, first[0].id,
            "the second run resolved to the task the first run created"
        );
        assert!(!first[0].reused, "the first run created the work");
        assert!(second[0].reused, "the second run reported that it did not");

        let live: Vec<String> = e
            .board(false)
            .unwrap()
            .into_iter()
            .map(|task| task.title)
            .collect();
        assert_eq!(live, vec![first[0].title.clone()]);
    }

    /// The boundary is live work, not history. Retiring a breakdown and asking
    /// for another is a deliberate act, and a run that answered with the
    /// abandoned task would leave the goal with no claimable work at all.
    #[test]
    fn a_retired_task_does_not_suppress_a_later_decomposition() {
        let e = engine();
        let g = e
            .define_goal(
                GoalKind::Objective,
                "Add search",
                "Implement FTS search",
                None,
            )
            .unwrap();

        let first = e.decompose_goal(&g.id).unwrap();
        assert!(e.abandon_task(&first[0].id, true).unwrap());
        let second = e.decompose_goal(&g.id).unwrap();

        assert_ne!(second[0].id, first[0].id);
        assert!(!second[0].reused);
    }

    /// Finished work must be findable by the only party who can move it.
    ///
    /// A task completing into `in_review` clears its owner, and a human has no
    /// agent id (ADR-0046), so it belongs to nobody and appears in no
    /// addressed queue. Measured on 2026-07-30: five tasks in review from at
    /// least three sessions, three of them more than a day old, surfaced
    /// nowhere but a board query somebody had to think to run.
    #[test]
    fn work_awaiting_a_human_reports_review_work_and_nothing_else() {
        let e = engine();
        let waiting = drive_to_review(&e, "agent-a");

        // Work an agent can still move must not appear: the whole value is that
        // everything in this list needs a person.
        let goal = e
            .define_goal(GoalKind::Objective, "Other", "other work", None)
            .unwrap();
        let open = e.create_task(&goal.id, "still claimable", "done").unwrap();
        e.claim_task(&open.id, "agent-b", 3600).unwrap();

        let awaiting = e.work_awaiting_a_human().unwrap();
        let ids: Vec<&str> = awaiting.iter().map(|s| s.task_id.as_str()).collect();
        assert_eq!(
            ids,
            vec![waiting.id.as_str()],
            "only the review work is waiting on a person: {awaiting:?}"
        );
        assert_eq!(awaiting[0].kind, crate::stalls::StallKind::AwaitingHuman);
        assert!(
            awaiting[0].stalled_seconds >= 0,
            "how long is reported, never judged"
        );
    }

    /// Silence is the point when nothing is waiting.
    ///
    /// A field that always appears is one readers learn to scroll past, and
    /// this one only earns attention on the day it is not empty.
    #[test]
    fn work_awaiting_a_human_is_empty_when_nobody_is_waiting() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = e.create_task(&goal.id, "claimable", "done").unwrap();
        e.claim_task(&task.id, "agent-a", 3600).unwrap();

        assert!(e.work_awaiting_a_human().unwrap().is_empty());
    }

    #[test]
    fn work_needing_rescue_includes_wait_cycles_but_not_ordinary_peer_waits() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Coordinate", "coordinate work", None)
            .unwrap();
        let first = e.create_task(&goal.id, "First", "done").unwrap();
        let second = e.create_task(&goal.id, "Second", "done").unwrap();
        let ordinary = e.create_task(&goal.id, "Ordinary wait", "done").unwrap();
        e.claim_task(&first.id, "agent-a", 600).unwrap();
        e.claim_task(&second.id, "agent-b", 600).unwrap();
        e.claim_task(&ordinary.id, "agent-c", 600).unwrap();
        e.ask_question(
            &first.id,
            "agent-a",
            "Are you changing this?",
            Some("agent-b"),
        )
        .unwrap();
        e.ask_question(
            &second.id,
            "agent-b",
            "Are you changing this?",
            Some("agent-a"),
        )
        .unwrap();
        e.ask_question(
            &ordinary.id,
            "agent-c",
            "Are you changing this?",
            Some("agent-d"),
        )
        .unwrap();

        let rescue = e.work_needing_rescue().unwrap();
        let mut ids: Vec<&str> = rescue.iter().map(|stall| stall.task_id.as_str()).collect();
        ids.sort_unstable();
        let mut expected = vec![first.id.as_str(), second.id.as_str()];
        expected.sort_unstable();
        assert_eq!(ids, expected);
        assert!(rescue
            .iter()
            .all(|stall| stall.kind == crate::stalls::StallKind::Deadlocked));
    }

    #[test]
    fn work_needing_rescue_reports_paused_work_only_after_the_parking_grace() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Pause", "pause work", None)
            .unwrap();
        let protected = e.create_task(&goal.id, "Protected pause", "done").unwrap();
        let overdue = e
            .create_task(&goal.id, "Owner disappeared", "done")
            .unwrap();
        e.claim_task(&protected.id, "agent-a", 600).unwrap();
        e.claim_task(&overdue.id, "agent-b", 600).unwrap();
        e.pause_task(&protected.id, "agent-a", Some("back soon"))
            .unwrap();
        e.store
            .pause_task(
                &overdue.id,
                "agent-b",
                Some("owner never returned"),
                crate::now_unix() - (7 * 24 * 3600) - 1,
            )
            .unwrap();

        let rescue = e.work_needing_rescue().unwrap();
        assert_eq!(rescue.len(), 1, "only the overdue pause is rescuable");
        assert_eq!(rescue[0].task_id, overdue.id);
        assert_eq!(rescue[0].kind, crate::stalls::StallKind::Paused);
        for (task, owner) in [(&protected, "agent-a"), (&overdue, "agent-b")] {
            let unchanged = e.store.get_task(&task.id).unwrap().unwrap();
            assert_eq!(unchanged.status, TaskStatus::Paused);
            assert_eq!(unchanged.owner.as_deref(), Some(owner));
        }
    }

    /// Drive a fresh task all the way to `in_review` through a real
    /// needs-human conformance completion, so the stored evidence records
    /// `agent` as the worker under review.
    fn drive_to_review(e: &crate::Lodestar, agent: &str) -> crate::Task {
        let goal = e
            .define_goal(GoalKind::Objective, "Ship auth", "change auth", None)
            .unwrap();
        let task = e.create_task(&goal.id, "change auth", "done").unwrap();
        e.claim_task(&task.id, agent, 300).unwrap();
        let claimed = e.store.get_task(&task.id).unwrap().unwrap();
        let evidence = crate::ConformanceEvidence {
            schema_version: 1,
            task_id: Some(task.id.clone()),
            agent_id: agent.into(),
            started_at: claimed.claim_started_at.unwrap(),
            ended_at: crate::now_unix(),
            changed_node_ids: Vec::new(),
            failed_node_ids: Vec::new(),
            execution_ids: Vec::new(),
            successful_execution_ids: Vec::new(),
            commit_ids: Vec::new(),
            ledger_act_ids: Vec::new(),
            summary: "no mutation evidence".into(),
            provenance: Vec::new(),
        };
        let checked = e.check_conformance(&evidence, Some(&task.id)).unwrap();
        assert_eq!(checked.verdict, crate::Verdict::NeedsHuman);
        let completion = e
            .complete_task(&task.id, agent, &evidence, &checked, None)
            .unwrap();
        let completed = completion.completed;
        assert!(!completed);
        assert_eq!(
            e.store.get_task(&task.id).unwrap().unwrap().status,
            TaskStatus::InReview
        );
        task
    }

    #[test]
    fn resolve_task_records_an_unverified_reviewer_label_on_acceptance() {
        let e = engine();
        let task = drive_to_review(&e, "agent-a");
        // This deliberately is not a credential or a known principal. Option 2
        // of ADR-0071 permits an arbitrary distinct label and records it for
        // attribution; it must never be described as authenticated identity.
        let label = "reviewed-by-lyndon (unverified label)";
        assert!(e.resolve_task(&task.id, label).unwrap());
        let resolved = e.store.get_task(&task.id).unwrap().unwrap();
        assert_eq!(resolved.status, TaskStatus::Done);
        assert_eq!(resolved.resolved_by.as_deref(), Some(label));
    }

    #[test]
    fn resolve_task_refuses_self_resolution_by_the_reviewed_agent() {
        let e = engine();
        let task = drive_to_review(&e, "agent-a");
        let err = e.resolve_task(&task.id, "agent-a").unwrap_err().to_string();
        assert!(err.contains("may not resolve its own"), "{err}");
        assert_eq!(
            e.store.get_task(&task.id).unwrap().unwrap().status,
            TaskStatus::InReview
        );
    }

    #[test]
    fn resolve_task_requires_a_non_empty_reviewer_label() {
        let e = engine();
        let task = drive_to_review(&e, "agent-a");
        let err = e.resolve_task(&task.id, "   ").unwrap_err().to_string();
        assert!(err.contains("reviewer label is required"), "{err}");
        assert!(err.contains("not authenticated"), "{err}");
    }

    #[test]
    fn resolve_task_refuses_a_task_that_is_not_in_review() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Ship", "do it", None)
            .unwrap();
        let task = e.create_task(&goal.id, "work", "done").unwrap();
        let err = e
            .resolve_task(&task.id, "reviewer")
            .unwrap_err()
            .to_string();
        assert!(err.contains("only an in_review task"), "{err}");
    }
